  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: var(--gray-5);
  border-radius: 9999px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--gray-7);
}

/* ── react-day-picker v8 — themed to Radix Themes orange/sand ── */
.rdp {
  --rdp-cell-size: 34px;
  --rdp-accent-color: var(--orange-9);
  --rdp-background-color: var(--orange-3);
  --rdp-outline: 2px solid var(--orange-9);
  --rdp-outline-selected: 2px solid var(--orange-9);
  margin: 0;
  font-family: inherit;
  font-size: var(--font-size-2);
}

